package com.gpldroid.qurankareem;import android.app.Activity;import android.os.Bundle;import android.webkit.WebView;import android.webkit.WebViewClient;import android.webkit.WebSettings;public class MainActivity extends Activity{private static final String URL="https://gpldroid.github.io/quran-karim/";public void onCreate(Bundle b){super.onCreate(b);WebView w=new WebView(this);w.setWebViewClient(new WebViewClient());WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);w.loadUrl(URL);setContentView(w);}}